const slim = results.map(t => ({
  id: t.id, subject: t.subject, group_id: t.group_id, status: t.status, requester_id: t.requester_id,
  created_at: t.created_at, assignee_id: t.assignee_id || null, description: String(t.description || '').slice(0, 200),
