  category: ((t.custom_fields || []).find(f => f.id === CAT) || {}).value || null,
}));
return [{ json: { source: 'gen_gq', results: slim, count: slim.length } }];

// Valid category options straight from Zendesk (source of truth, the Sheets directory can be outdated)
const opts = $('Get Category Options').first().json.ticket_field?.custom_field_options || [];
const tags = opts.map(o => o.value);
// Catalog for the agent prompt: "Name → tag" (internal categories left out, they are never customer tickets)
const catalog = opts.filter(o => !/^Internal::/i.test(o.name)).map(o => o.name + ' → ' + o.value).join('\n');
// Agent availability (v11): owners with agent_ooo=true (or suspended/inactive) get covered in Build Zendesk Update
const KEYS = { justin: 54788295418644, sudu: 24567978777492, jaime: 55350915332244, caro: 32288140085012, cristian: 48493524357268, brisa: 47071350698516, miguel: 28269839522452, samuel: 40230868739348, mike: 42677627758740 };
let users = [];
try { users = $('Get Agent Availability').first().json.users || []; } catch (e) { users = []; }
const ooo_ids = users.filter(u => u.agent_ooo === true || u.suspended === true || u.active === false).map(u => u.id);
const ooo = Object.keys(KEYS).filter(k => ooo_ids.includes(KEYS[k]));
return [{ json: { source: 'lookups', tags, catalog, ooo, ooo_ids, availability_loaded: users.length > 0 } }];

// v11: two kinds of work per run.
//  (a) NEW: unassigned new/open tickets in Worker Support + Company Support (max 5).
//  (b) SWEEP (re-route): tickets still in a generic category (Worker General Info / General questions),
//      >= 30 min old, unassigned / with Samuel / with an OOO agent, not yet re-routed (max 3).
//  (c) CATEGORY-ONLY (v11.4): generic-category tickets already with a real owner → Nova sets the right
//      category + note, keeps the assignee (max 3). Tag nova_categorized (once).
const WS = 22616861202452, CS = 23897889259668, CAT = 22865771347348;
const SAMUEL = 40230868739348;
const EXCLUDED = [253224, 250770, 250793];
const KEEP = [256002, 256471, 255983, 256648, 256791]; // humans decided these stay with the current owner (or tag nova_keep_owner)
const GENERIC = ['account__worker_general_info', 'account__client_general_info', 'account__general_questions__account_'];
const MAX_NEW = 5, MAX_SWEEP = 3, MAX_RECAT = 3, SWEEP_MIN_AGE_MIN = 30;
const now = Date.now();
// v11.3: everything arrives through the Merge node input — no $() lookups (they made the task runner pull the whole execution and stall)
const items = $input.all().map(i => i.json);
const L = items.find(x => x.source === 'lookups') || {};
const OOO_IDS = L.ooo_ids || [];
const res = src => (items.find(x => x.source === src) || {}).results || [];
const ageMin = t => (now - new Date(t.created_at).getTime()) / 60000;
const cat = t => t.category || null;
const row = (t, mode) => ({ json: {
  ticket_id: t.id, subject: t.subject, group_id: t.group_id, status: t.status,
  requester_id: t.requester_id, created_at: t.created_at, current_category: cat(t),
  current_assignee: t.assignee_id || null, channel: t.channel, tags: t.tags, mode,
}});
const out = [];
const seen = new Set();
// (a) NEW
const fresh = [...res('new_ws'), ...res('new_cs')]
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
for (const t of fresh) {
  if (out.length >= MAX_NEW) break;
  if (![WS, CS].includes(t.group_id) || t.assignee_id || EXCLUDED.includes(t.id) || seen.has(t.id)) continue;
  const tg = t.tags || [];
  if (tg.includes('nova_routing_failed')) continue; // both writes failed before — a human handles it
  const looksEmptyHandoff = /^Conversation with/i.test(t.description || '') && tg.includes('ada_messaging_handoff');
  if (looksEmptyHandoff && ageMin(t) < 10) continue; // next run picks it up once the customer has written
  seen.add(t.id); out.push(row(t, 'new'));
}
// (b) SWEEP generic categories
const generic = [...res('gen_wgi'), ...res('gen_gq')]
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
let sweep = 0, recat = 0;
for (const t of generic) {
  if (sweep >= MAX_SWEEP && recat >= MAX_RECAT) break;
  if (![WS, CS].includes(t.group_id) || EXCLUDED.includes(t.id) || seen.has(t.id)) continue;
  if (!GENERIC.includes(cat(t))) continue;
  const tg = t.tags || [];
  if (['nova_reasignado', 'nova_categorized', 'nova_routing_failed', 'nova_low_context', 'nova_followup_entrega'].some(x => tg.includes(x))) continue;
  if (ageMin(t) < SWEEP_MIN_AGE_MIN) continue; // give the customer time to explain
  const a = t.assignee_id || null;
  const unowned = a === null || a === SAMUEL || OOO_IDS.includes(a);
  if (unowned && !KEEP.includes(t.id) && !tg.includes('nova_keep_owner')) {
    if (sweep >= MAX_SWEEP) continue;
    seen.add(t.id); out.push(row(t, 'reroute')); sweep++;
  } else if (a !== null) {
    // (c) v11.4 CATEGORY-ONLY: already with a real owner (or a human kept it there) → fix the category, never touch the assignee
    if (recat >= MAX_RECAT) continue;
    seen.add(t.id); out.push(row(t, 'recat')); recat++;
  }
}
return out;

