={{ (() => {
  const d = $json.output || {};
  const tk = $('Loop Over Tickets').item.json || {};
  const L = $('Prepare Lookups').first().json || {};
  const A = { justin: 54788295418644, sudu: 24567978777492, jaime: 55350915332244, caro: 32288140085012, cristian: 48493524357268, brisa: 47071350698516, miguel: 28269839522452, samuel: 40230868739348, mike: 42677627758740 };
  const N = { justin: 'Justin', sudu: 'Sudu', jaime: 'Jaime', caro: 'Caro', cristian: 'Cristian', brisa: 'Brisa', miguel: 'Miguel', samuel: 'Samuel', mike: 'Mike' };
  const S = { justin: 'U0CA6JRHVM3', sudu: 'U03U61FQJKA', jaime: 'U0CEQGZN7AB', caro: 'U063KEHP2SD', cristian: 'U0AU0TPJDM5', brisa: 'U0AJMGBVCR5', miguel: 'U06LW3ASH7D', samuel: 'U099JCSKB3Q', mike: 'U09NCCJJ2UT' };
  const COVER = { sudu: 'justin', brisa: 'cristian', justin: 'sudu', jaime: 'caro', caro: 'jaime', cristian: 'brisa', miguel: 'samuel', samuel: 'miguel', mike: 'miguel' };
  const OOO = L.ooo || [];
  const CS = 23897889259668, CAT = 22865771347348, TOR = 32273934250132, PAYFLOW = 25216334038676;
  const TORV = { issue: 'issue_request', question: 'question_request', product_feedback: 'product_feedback_request', internal_process: 'internal_process_request' };
  const GENERIC = ['account__worker_general_info', 'account__client_general_info', 'account__general_questions__account_'];
  const MSG = ['whatsapp', 'native_messaging', 'sunshine_conversations_api', 'sunshine_conversations_facebook_messenger', 'chat', 'instagram_dm', 'line', 'telegram', 'wechat'];
  if (!d.owner_key || !d.ticket_id || !A[d.owner_key]) return JSON.stringify({ skip: true, urgent: false, error: 'Agent returned no valid decision' });
  const tags = L.tags || [];
  const reroute = tk.mode === 'reroute';
  const recat = tk.mode === 'recat';
  let o = d.owner_key; const notes = []; let conf = d.confidence; let byDup = false;
  if (reroute) notes.push('Re-route sweep: this ticket was still in a generic category (' + (tk.current_category || '-') + ')' + (tk.current_assignee ? ' with agent ' + tk.current_assignee : ' without owner') + ' — re-read and reassigned to the domain owner.');
  // 1) Same requester + SAME issue already assigned to a current owner → same agent
  const dupOwner = Object.keys(A).find(k => A[k] === Number(d.duplicate_assignee_id));
  if (d.same_issue_duplicate_of && dupOwner) {
    o = dupOwner; byDup = true;
    notes.push('Same issue as #' + d.same_issue_duplicate_of + ' (already with ' + N[o] + ') — assigned to the same agent. Please check and merge.');
  } else if (d.low_context) {
    // 2) Low-context (nothing useful in comments, conversation log AND Aura chat history) → general questions owner
    o = d.requester_type === 'client' ? 'miguel' : 'cristian';
    notes.push('Low-context ticket — assigned to ' + N[o] + ' (general questions). ' + (reroute ? 'Still no real ask after the re-check.' : 'Nova re-checks it after 30 min in case the customer writes more.'));
  }
  // v11.4 category-only: keep the current assignee; only flag a domain mismatch in the note
  const curKey = Object.keys(A).find(k => A[k] === Number(tk.current_assignee));
  if (recat) {
    const dom = o;
    notes.length = 0;
    notes.push('Category-only pass: ticket already had an owner but a generic category (' + (tk.current_category || '-') + ') — Nova re-read it and set the specific category. Assignee NOT changed.');
    if (curKey && dom !== curKey) notes.push('Heads-up: by domain this looks like ' + N[dom] + "'s — reassign only if it makes sense (current: " + N[curKey] + ').');
    if (!curKey) notes.push('Current assignee (' + tk.current_assignee + ') is outside the routing roster — domain owner would be ' + N[dom] + '.');
    if (curKey) o = curKey;
  }
  // 3) Availability: owner out of office → cover
  if (!recat && OOO.includes(o)) {
    const c = COVER[o];
    if (c && !OOO.includes(c)) { notes.push(N[o] + ' is out of office — covered by ' + N[c] + '.'); o = c; }
    else notes.push(N[o] + ' is out of office and the cover is not available — please reassign manually.');
  }
  // 4) Category: must exist in Zendesk; generic ones only for low-context
  const isGeneric = GENERIC.includes(d.category_tag);
  const tagOk = tags.includes(d.category_tag) && !(isGeneric && !d.low_context);
  if (!tags.includes(d.category_tag)) notes.push('Suggested category "' + d.category_name + '" not set: tag "' + d.category_tag + '" is not a valid option.');
  else if (isGeneric && !d.low_context) { conf = 'low'; notes.push('Generic category "' + d.category_name + '" not saved because the ticket has a real ask — please set the specific category.'); }
  if (d.requester_type === 'client' && conf !== 'high' && !byDup) notes.push("I don't have a high confidence score on what the client needs — please review, and if it's not for you, assign it to " + (o === 'miguel' ? 'Samuel' : 'Miguel') + '. Thanks! 🙌');
  if (!byDup && (d.possible_duplicate_of || []).length) notes.push('Possible duplicate of #' + d.possible_duplicate_of.join(', #') + ' — please check and merge if it is the same issue; otherwise handle as a normal ticket.');
  if (d.possible_product_issue) notes.push('Possible product/tech issue: "' + (d.issue_signature || '') + '" — ask for a screenshot or screen recording (device, app version, time of the error) so it can be escalated to Tech/Product.');
  // 5) How to reply on this channel (v11)
  const ch = tk.channel || '';
  if (MSG.includes(ch)) {
    const last = d.last_customer_message_at ? Date.parse(d.last_customer_message_at) : NaN;
    const hrs = isNaN(last) ? null : (Date.now() - last) / 36e5;
    const lang = d.reply_language === 'en' ? 'en' : 'es';
    let line = '📱 Messaging ticket (' + ch + '): reply from Agent Workspace (or the Sunshine Conversations API). Public comments posted through the Ticket API do NOT reach the customer.';
    if (ch === 'whatsapp') {
      if (hrs === null) line += ' Last customer message time unknown — check the WhatsApp 24h window before replying.';
      else if (hrs > 24) line += ' ⏰ WhatsApp 24h window is CLOSED (last customer message ~' + Math.round(hrs) + 'h ago): first send the template "reactivar_conversacion" (' + lang + '); send the reply only after the customer answers it.';
      else line += ' WhatsApp 24h window open (last customer message ~' + Math.round(hrs) + 'h ago, closes in ~' + Math.max(0, Math.round(24 - hrs)) + 'h).';
    }
    notes.push(line);
  }
  const rt = TORV[d.request_type] || '';
  const body = [
    '🤖 Nova · Domain routing + diagnosis (n8n AI agent v11.4' + (reroute ? ', re-route sweep' : recat ? ', category only' : '') + ') · ' + $now.setZone('America/Bogota').toFormat('dd LLL HH:mm') + ' COL',
    'Category → ' + d.category_name + ' · Type: ' + (d.request_type || '-') + ' · Owner: ' + N[o] + ' · Confidence: ' + conf,
    '• Ask: ' + (d.ask || d.reason),
    '• Onsight: ' + (d.onsight_facts || d.verified_facts || 'not verified'),
    '• Side conversations: ' + (d.side_conversations || 'none'),
    '• Duplicates: ' + ((d.possible_duplicate_of || []).length ? '#' + d.possible_duplicate_of.join(', #') : 'none'),
    '• Suggested action: ' + (d.suggested_action || '-') + ' (owner: ' + N[o] + ')',
    '• Suggested reply' + (d.reply_language ? ' (' + d.reply_language + ')' : '') + ': "' + (d.suggested_reply || '') + '"',
    'Routing reason: ' + d.reason
  ].concat(notes).concat(['This is a suggestion — please validate before sending 🙌']).filter(Boolean).join('\n');
  const cf = [];
  if (tagOk) cf.push({ id: CAT, value: d.category_tag });
  if (rt) cf.push({ id: TOR, value: rt });
  // recat: never send assignee_id / group_id (owner stays as is)
  const own = recat ? {} : { assignee_id: A[o] };
  const grp = !recat && d.requester_type === 'client';
  const t = { ...own, comment: { public: false, body } };
  if (cf.length) t.custom_fields = cf;
  if (grp) t.group_id = CS;
  // Retry: same update + Payflow = n/a (Zendesk rejects some categories with "Payflow: needed")
  const r = { ...own, comment: { public: false, body }, custom_fields: cf.concat([{ id: PAYFLOW, value: 'n/a' }]) };
  if (grp) r.group_id = CS;
  const f = { ...own, comment: { public: false, body: body + '\n(Category / type of request could not be saved automatically — required fields missing. Please set them when working the ticket.)' } };
  if (grp) f.group_id = CS;
  const add = [reroute ? 'nova_reasignado' : recat ? 'nova_categorized' : 'nova_routed'];
  if (d.low_context) add.push('nova_low_context');
  if (!tagOk && GENERIC.includes(tk.current_category || '')) add.push('nova_needs_category');
  const addFallback = [...new Set(add.concat(['nova_needs_category']))];
  return JSON.stringify({ skip: false, ticket_id: d.ticket_id, mode: tk.mode || 'new', channel: ch, owner: N[o], owner_slack_id: S[o] || '', category_name: d.category_name, category_tag: d.category_tag, category_saved: tagOk, request_type: rt, confidence: conf, low_context: !!d.low_context, urgent: !!d.urgent, urgent_reason: d.urgent_reason || '', same_issue_duplicate_of: d.same_issue_duplicate_of || '', assigned_by_duplicate: byDup, possible_product_issue: !!d.possible_product_issue, issue_signature: d.issue_signature || '', reason: d.reason || '', update: { ticket: t }, retry: { ticket: r }, fallback: { ticket: f }, add_tags: add, add_tags_fallback: addFallback });
})() }}

